/** Uma única atualização de texto; os IDs e toda a direção sonora são mantidos. */
export function applySceneTextUpdate(state){
  if(state.sceneTextRevision===SCENE_TEXT_REVISION)return false;
  const page=state.campaigns.find(c=>c.id==='reescritos')?.pages.find(p=>p.id==='sao-martinho');
  for(const scene of page?.scenes||[]){
    const next=updatedScenes[scene.id];if(next===undefined||scene.markdown===next)continue;
    scene.textHistory??=[];scene.textHistory.push({title:'Antes da atualização de 19/10/2026',at:new Date().toISOString(),markdown:scene.markdown});scene.markdown=next;
  }
  state.sceneTextRevision=SCENE_TEXT_REVISION;return true;
}
